local function wedgeFace(parent, a, b, c, color)
	local ab, ac, bc = b - a, c - a, c - b
	if ab.Magnitude > ac.Magnitude and ab.Magnitude > bc.Magnitude then
		a, c = c, a
	elseif ac.Magnitude > ab.Magnitude and ac.Magnitude > bc.Magnitude then
		a, b = b, a
	end
	ab, ac, bc = b-a, c-a, c-b
	local normal = ac:Cross(ab)
	if normal.Magnitude < 0.0001 then return end
	local right, back = normal.Unit, bc.Unit
	local up = back:Cross(right).Unit
	local height = math.abs(ab:Dot(up))
	local function half(mid, x, z, width)
		if width < 0.001 then return end
		local part = Instance.new("WedgePart")
		part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery = true, false, false, false
		part.CastShadow = false
		part.Material, part.Color = Enum.Material.SmoothPlastic, color
		part.Size = Vector3.new(0.05, height, width)
		part.CFrame = CFrame.fromMatrix(mid, x, up, z)
		part.Parent = parent
	end
	half((a+b)/2, right, back, math.abs(ab:Dot(back)))
	half((a+c)/2, -right, -back, math.abs(ac:Dot(back)))
end

-- Shared prototypes avoid repeated mesh allocations for identical world props.
-- Geometry fallback is selected globally after the first unavailable mesh allocation.
local prototypes={}
local prototypeCount=0
local editableAvailable=true
local function prototype(shapeName,scale)
	local key=shapeName..":"..tostring(scale)
	local cached=prototypes[key]
	if cached then
		while cached.building do task.wait() end
		return cached.visual,false
	end
	local shape=shapes[shapeName]
	if not shape then return nil,false end
	local retain=prototypeCount<48
	local entry={building=true}
	if retain then prototypes[key]=entry;prototypeCount+=1 end
	local vertices={}
	local low=Vector3.new(math.huge,math.huge,math.huge)
	local high=Vector3.new(-math.huge,-math.huge,-math.huge)
	for _,xyz in ipairs(shape.vertices) do
		local v=Vector3.new(table.unpack(xyz))*scale
		table.insert(vertices,v)
		low=Vector3.new(math.min(low.X,v.X),math.min(low.Y,v.Y),math.min(low.Z,v.Z))
		high=Vector3.new(math.max(high.X,v.X),math.max(high.Y,v.Y),math.max(high.Z,v.Z))
	end
	local mesh,visual
	if editableAvailable and retain then
		local ok,result=pcall(function()
			mesh=AssetService:CreateEditableMesh()
			assert(mesh,"Editable mesh unavailable")
			local ids,shades={},{}
			for _,v in ipairs(vertices) do table.insert(ids,mesh:AddVertex(v)) end
			for _,color in ipairs(palette) do table.insert(shades,mesh:AddColor(color,1)) end
			for _,f in ipairs(shape.faces) do
				local face=mesh:AddTriangle(ids[f[1]],ids[f[2]],ids[f[3]])
				mesh:SetFaceColors(face,{shades[f[4]],shades[f[4]],shades[f[4]]})
			end
			local p=AssetService:CreateMeshPartAsync(Content.fromObject(mesh))
			p.DoubleSided=true
			p.Anchored,p.CanCollide,p.CanTouch,p.CanQuery=true,false,false,false
			p.Material=Enum.Material.SmoothPlastic
			-- MeshPart geometry is centered on its bounding box. Preserve the
			-- authored origin so native and wedge fallback silhouettes align.
			p.PivotOffset=CFrame.new(-(low+high)/2)
			return p
		end)
		if ok then visual=result else
			editableAvailable=false
			if mesh then mesh:Destroy();mesh=nil end
		end
	end
	if not visual then
		visual=Instance.new("Model")
		for _,f in ipairs(shape.faces) do wedgeFace(visual,vertices[f[1]],vertices[f[2]],vertices[f[3]],palette[f[4]]) end
		visual.WorldPivot=CFrame.new()
	end
	visual.Name=shapeName.." Sculpture"
	entry.visual,entry.mesh,entry.building=visual,mesh,false
	return visual,not retain
end
local function build(anchor)
	local shapeName=anchor:GetAttribute("Shape")
	if not shapes[shapeName] then return end
	local scale=anchor:GetAttribute("SculptureScale") or 1
	if type(scale)~="number" or scale<=0 or scale>100 or scale~=scale then return end
	local template,temporary=prototype(shapeName,scale)
	if not template then return end
	local visual=if temporary then template else template:Clone()
	if not anchor.Parent then visual:Destroy();return end
	visual:PivotTo(anchor.CFrame)
	visual.Parent=anchor
	local motion
	if shapeName=="Tidewing" then
		local elapsed=0
		motion=RunService.Heartbeat:Connect(function(dt)
			elapsed+=dt
			if elapsed<1/18 then return end
			elapsed=0
			local t=workspace:GetServerTimeNow()*.42
			visual:PivotTo(anchor.CFrame*CFrame.new(0,1.5*math.sin(t),0)*CFrame.Angles(0,math.rad(5)*math.cos(t),math.rad(5)*math.sin(t)))
		end)
	end
	anchor.Destroying:Once(function() if motion then motion:Disconnect() end end)
end
script.Destroying:Once(function()
	for _,entry in pairs(prototypes) do
		if entry.visual then entry.visual:Destroy() end
		if entry.mesh then entry.mesh:Destroy() end
	end
end)

local processed = setmetatable({}, {__mode="k"})
local function attach(anchor)
	if processed[anchor] then return end
	processed[anchor] = true
	task.spawn(build, anchor)
end
CollectionService:GetInstanceAddedSignal("AetherSculpture"):Connect(attach)
for _, anchor in ipairs(CollectionService:GetTagged("AetherSculpture")) do attach(anchor) end

-- Each client renders companions from server-owned bond attributes.
local Players = game:GetService("Players")
local companions = {}
local function updateCompanion(player)
	local character = player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local bonded = (player:GetAttribute("CompanionBond") or 0) > 0
	local anchor = companions[player]
	if not bonded or not root then
		if anchor then anchor:Destroy(); companions[player] = nil end
		return
	end
	if not anchor then
		anchor = Instance.new("Part")
		anchor.Name = "Tidewing companion"
		anchor.Anchored = true
		anchor.CanCollide = false
		anchor.CanTouch = false
		anchor.CanQuery = false
		anchor.Transparency = 1
		anchor:SetAttribute("Shape", "Tidewing")
		anchor:SetAttribute("SculptureScale", 0.16)
		anchor.CFrame = root.CFrame * CFrame.new(3, 2, 2)
		anchor.Parent = workspace
		companions[player] = anchor
		attach(anchor)
	end
	anchor.CFrame = root.CFrame * CFrame.new(3, 2, 2)
end
local companionElapsed = 0
RunService.Heartbeat:Connect(function(dt)
	companionElapsed += dt
	if companionElapsed < 1/18 then return end
	companionElapsed = 0
	for _, player in Players:GetPlayers() do updateCompanion(player) end
end)
Players.PlayerRemoving:Connect(function(player)
	if companions[player] then companions[player]:Destroy(); companions[player] = nil end
end)
